upd AS (
  UPDATE movimenti_bancari m
  SET importo = c.importo_ok
  FROM corrections c
  WHERE m.descrizione = c.descrizione
    AND m.data_movimento = c.data_movimento
    AND m.stato IN ('importato','matchato','assegnato')
    AND round(m.importo::numeric, 2) IS DISTINCT FROM round(c.importo_ok, 2)
  RETURNING m.id, m.importo AS new_importo
)
SELECT count(*)::int AS updated, coalesce(sum(new_importo),0)::numeric AS sum_new FROM upd;
